select count(*) as a, count(maybe_n) as b, count(distinct name) as c, sum(n) as d, avg(n) as e, max(n) as f, min(name) as g, max(day) as h, group_concat(name) as i, bit_or(n) as j, bit_and(n) as k, bit_xor(n) as l, std(n) as m, variance(n) as o, json_arrayagg(n) as p, json_objectagg(id, n) as q, sum(1) as r, max(1) as s, any_value(n) as u, count(*) + 1 as v, coalesce(sum(n), 0) as w, sum(n) is null as x, min(at) as z, avg(price) as aa, sum(ratio) as ab, max(doc) as ac, min(kind) as ad, max(tags) as ae, max(bits) as af, min(flag) as ag, max(y) as ah, max(tm) as ai, var_samp(n) as aj, stddev_samp(n) as ak from t where n between -1 and 2
